      "Κύηση (ιδίως 1ο τρίμηνο).",
      "Προκωματώδης κατάσταση από ηπατική κίρρωση (η υποκαλιαιμία και η αλκάλωση αυξάνουν την αμμωνία).",
      "Υπονατριαιμία ή υποκαλιαιμία (προσοχή σε ηλικία > 70 ετών, γυναίκες, χαμηλό ΔΜΣ, συγχορήγηση SSRIs, ΜΣΑΦ, α-ΜΕΑ)."
