      "Γενετική προδιάθεση στην υπονατριαιμία: η παραλλαγή A396T του γονιδίου SLCO2A1 μειώνει τη λειτουργία του μεταφορέα προσταγλανδινών (PGT) → λιγότερη PGE₂ απομακρύνεται από τον αυλό → η PGE₂ δρα στους υποδοχείς EP4 των θεμέλιων κυττάρων → ↑ ενσωμάτωση υδατοπορινών AQP2 → ↑ επαναρρόφηση νερού ανεξάρτητα από την ADH.",
