    "abbreviations": "Συντομογραφίεςα-ΜΕΑ: αναστολείς του μετατρεπτικού ενζύμου της αγγειοτενσίνηςΑΥΑ: αποκλειστές των υποδοχέων της αγγειοτενσίνης ΙΙ (σαρτάνες)ΡΑΑ: σύστημα ρενίνης-αγγειοτενσίνης-αλδοστερόνηςΧΝΑ: χρόνια νεφρική ανεπάρκεια (νόσος)GFR: glomerular filtration rate = ρυθμός σπειραματικής διήθησηςΣΔ: σακχαρώδης διαβήτηςΣΝΣ: συμπαθητικό νευρικό σύστημαΜΣΑΦ: μη στεροειδή αντιφλεγμονώδη φάρμακαSSRIs: selective serotonin reuptake inhibitors = εκλεκτικοί αναστολείς επαναπρόσληψης σεροτονίνηςADH: antidiuretic hormone = αντιδιουρητική ορμόνη (βαζοπρεσίνη)ΔΜΣ: δείκτης μάζας σώματοςΝΟ: μονοξείδιο του αζώτουSLCO2A1: γονίδιο του μεταφορέα προσταγλανδινώνPGT: μεταφορέας προσταγλανδινώνAQP2: υδατοπορίνη 2PGE₂: προσταγλανδίνη E₂",
