      "Στην καρδιακή ανεπάρκεια δρουν με τρεις τρόπους: (1) σύνθεση προσταγλανδινών → φλεβική και πνευμονική αγγειοδιαστολή → ↓ πιέσεις πλήρωσης πριν ακόμη αρχίσει η διούρηση, (2) αρνητικό ισοζύγιο Na⁺ και νερού → ↓ διάταση και τάση τοιχώματος της αριστερής κοιλίας, ↓ λειτουργική ανεπάρκεια μιτροειδούς, (3) αναστολή της πυκνής κηλίδας → ↑ ΡΑΑ (ανεπιθύμητο)."
