      "Σπιρονολακτόνη, επλερενόνη: ανταγωνισμός του υποδοχέα αλδοστερόνης → ↓ σύνθεση των διαύλων ENaC και της αντλίας Na⁺/K⁺ → ↓ επαναρρόφηση Na⁺ και ↓ έκκριση K⁺ και H⁺.",
