      "Αγγειοοίδημα (< 1%): πρόσωπο, στόμα, ανώτερο αναπνευστικό, έντερο. Σπάνιο αλλά απειλητικό για τη ζωή.",
      "Υπερκαλιαιμία (προσοχή με καλιοσυντηρητικά διουρητικά και ΜΣΑΦ).",
      "Οξεία νεφρική βλάβη σε στένωση νεφρικής αρτηρίας ή με ΜΣΑΦ.",
      "Υπόταση πρώτης δόσης, δυσγευσία, εξάνθημα.",
      "Τερατογένεση και εμβρυϊκός θάνατος στο 2ο και 3ο τρίμηνο (ολιγοϋδράμνιο)."
