      "Προφάρμακα: μεταβολίζονται στο ήπαρ σε ενεργούς μεταβολίτες, εκτός από την καπτοπρίλη και τη λισινοπρίλη (που προτιμώνται σε ηπατική νόσο). Αποβάλλονται από τους νεφρούς, εκτός από τη φοσινοπρίλη (διπλή, ηπατική και νεφρική, αποβολή)."
