      "Το ΜΕΑ είναι και κινινάση ΙΙ → η αναστολή του αυξάνει τη βραδυκινίνη → ↑ ΝΟ και προσταγλανδίνες → επιπλέον αγγειοδιαστολή, αλλά και βήχας και αγγειοοίδημα.",
