      "Νεφραγγειακή υπέρταση: οι ασθενείς είναι ιδιαίτερα ευαίσθητοι, η αγωγή αρχίζει με μικρότερες δόσεις.",
      "Καρδιακή ανεπάρκεια σε όλα τα στάδια: βελτιώνουν την πρόγνωση (πλεονεκτούν του συνδυασμού νιτρωδών με υδραλαζίνη).",
      "Μετά από έμφραγμα με καρδιακή ανεπάρκεια ή δυσλειτουργία της αριστερής κοιλίας: έναρξη 3–10 ημέρες μετά, σε κλινικά σταθεροποιημένους ασθενείς.",
      "Διαβητική νεφροπάθεια (ΣΔ τύπου 1 με λευκωματουρία > 500 mg/24 h): αναστέλλουν την πρόοδο."
