    "mechanism": [
      "Αποκλεισμός του υποδοχέα AT₁ → ↓ αγγειοσύσπαση, ↓ αλδοστερόνη, ↓ υπερτροφία και αγγειογένεση. Ο υποδοχέας AT₂ μένει ελεύθερος → αγγειοδιαστολή και νατριούρηση.",
      "Δεν αναστέλλουν την κινινάση ΙΙ → δεν αυξάνουν τη βραδυκινίνη → σπανιότερος βήχας και αγγειοοίδημα από τους α-ΜΕΑ.",
      "Κυρίως ηπατική κάθαρση.",
      "Ο αποκλεισμός του AT₁ αφαιρεί την αρνητική ανάδραση → αύξηση της ρενίνης και της αγγειοτενσίνης Ι και ΙΙ στο πλάσμα, με μείωση της αλδοστερόνης."
    ],
    "indications": [
      "Υπέρταση.",
      "Διαβητική νεφροπάθεια, διαβητική μικρολευκωματινουρία, ΧΝΑ.",
      "Υπερτροφία της αριστερής κοιλίας, καρδιακή ανεπάρκεια.",
      "Βήχας από α-ΜΕΑ (εναλλακτική επιλογή)."
    ],
    "contraindications": [
      "Κύηση και γαλουχία.",
      "Υπερκαλιαιμία.",
      "Αμφοτερόπλευρη στένωση νεφρικών αρτηριών ή στένωση της αρτηρίας μονήρους νεφρού (προσοχή).",
      "Συγχορήγηση με α-ΜΕΑ ή αλισκιρένη."
    ],
    "adverse_effects": [
      "Υπερκαλιαιμία, συγκοπή και οξεία νεφρική βλάβη σε ποσοστά παρόμοια με των α-ΜΕΑ.",
      "Υπόταση πρώτης δόσης συχνότερα από τους α-ΜΕΑ, αλλά λιγότερες διακοπές της αγωγής.",
      "Επιδείνωση νεφρικής λειτουργίας σε στένωση νεφρικής αρτηρίας.",
      "Τερατογένεση (αντένδειξη στην εγκυμοσύνη).",
      "Συμπτωματική υπόταση και ζάλη, κυρίως με μειωμένο ενδαγγειακό όγκο ή υπονατριαιμία (π.χ. υψηλές δόσεις διουρητικών).",
      "Αγγειοοίδημα έχει αναφερθεί και με ΑΥΑ (σπάνια). Διαταραχές ηπατικής λειτουργίας."
    ],
    "pearls": [
      "Όχι συγχορήγηση με α-ΜΕΑ.",
      "Παρακολούθηση του καλίου ορού σε έκπτωση της νεφρικής λειτουργίας και σε ηλικιωμένους."
    ],
