      "Δεν έχουν δυσμενείς μεταβολικές επιδράσεις και φαίνεται να επιδρούν ευνοϊκά στα λιπίδια, αλλά δεν είναι ισχυρά αντιυπερτασικά σε μονοθεραπεία."
