      "Το ενδοθηλιακό ΝΟ σχηματίζεται από τη συνθάση ΝΟ (NOS3) από L-αργινίνη και, εκτός από τη χάλαση, αναστέλλει τη συσσώρευση αιμοπεταλίων, την προσκόλληση μονοκυττάρων και τον πολλαπλασιασμό των λείων μυϊκών ινών."
