    "brands_str": "FORXIGA, XIGDUO, όλα τα σκευάσματα στον Γαληνό",
    "mechanism": [
      "Αναστολή του SGLT2 στο τμήμα S1 του εγγύς εσπειραμένου σωληναρίου, όπου επαναρροφάται ~90% της διηθούμενης γλυκόζης (το υπόλοιπο ~10% από τον SGLT1) → γλυκοζουρία → απώλεια ~320 kcal/ημέρα.",
      "Μηχανισμός ανεξάρτητος από την ινσουλίνη → χωρίς υπογλυκαιμία. Επειδή εξαρτάται από τη διηθούμενη γλυκόζη, η γλυκαιμική δράση μειώνεται όταν eGFR < 45.",
      "Συνδιούρηση Na⁺ → αποκατάσταση της σωληναριοσπειραματικής ανάδρασης → σύσπαση του προσαγωγού αρτηριδίου → ↓ ενδοσπειραματική πίεση → νεφροπροστασία. ↓ όγκος πλάσματος και προφόρτιο → καρδιοπροστασία."
    ],
    "indications": [
      "ΣΔ τύπου 2 με αθηροσκληρωτική καρδιαγγειακή νόσο, καρδιακή ανεπάρκεια ή ΧΝΝ: από την αρχή, ανεξάρτητα από την HbA1c.",
      "Καρδιακή ανεπάρκεια ανεξάρτητα από το κλάσμα εξώθησης και ΧΝΝ, με ή χωρίς ΣΔ (δαπα- και εμπαγλιφλοζίνη 10 mg, έως eGFR > 20).",
      "Μείωση βάρους, αρτηριακής πίεσης και ουρικού οξέος. Μείωση HbA1c ~0,5–0,7%.",
      "Καρδιακή ανεπάρκεια: μπορεί να αρχίσει ή να συνεχιστεί στη νοσηλεία και στο εξιτήριο, μετά την ανάρρωση από την οξεία φάση.",
      "Ηλικιωμένοι: παρόμοια ή μεγαλύτερα οφέλη σε σχέση με τους νεότερους."
    ],
    "contraindications": [
      "Ως αντιδιαβητικά: πλήρης δόση σε eGFR > 60. Δαπαγλιφλοζίνη: όχι έναρξη σε eGFR < 25. Καναγλιφλοζίνη: όχι έναρξη σε eGFR < 30, διακοπή σε < 15.",
      "ΣΔ τύπου 1 και ινσουλινοπενία: κίνδυνος ευγλυκαιμικής κετοξέωσης.",
      "Διακοπή 2–3 ημέρες πριν από προγραμματισμένη χειρουργική επέμβαση και σε οξύ στρες (λοίμωξη, τραύμα).",
      "Αφυδάτωση: προσοχή στους ηλικιωμένους.",
      "Οξεία σοβαρή νόσος, κετοναιμία ή κετονουρία, παρατεταμένη νηστεία: αποφυγή ή άμεση διακοπή. Περιεγχειρητικά διακοπή για 3 ημέρες.",
      "Νοσηλεία για υπεργλυκαιμία: διακοπή και ποτέ έναρξη. Μετά από ευγλυκαιμική κετοξέωση υπό SGLT2: οριστική διακοπή."
    ],
    "adverse_effects": [
      "Λοιμώξεις του ουροποιητικού και του γεννητικού συστήματος (μυκητιάσεις), ιδίως στις γυναίκες. Γάγγραινα Fournier (σπάνια).",
      "Ευγλυκαιμική διαβητική κετοξέωση: ένδεια ινσουλίνης → ↑ γλυκαγόνη, κορτιζόλη, αδρεναλίνη → λιπόλυση → κετονοσώματα, με φυσιολογική γλυκόζη (επειδή η γλυκόζη χάνεται στα ούρα).",
      "Αφυδάτωση, υπόταση. Αύξηση της LDL χοληστερόλης.",
      "Καναγλιφλοζίνη: κατάγματα, ακρωτηριασμοί κάτω άκρων, περιφερική αγγειοπάθεια."
    ],
