      "Ο ασθενής εκπαιδεύεται να αναγνωρίζει τα σημεία της κετοξέωσης (ναυτία, έμετος, κοιλιακό άλγος, δύσπνοια) ακόμη και με φυσιολογική γλυκόζη, και να μετρά κετόνες."
