    "mechanism": [
      "Τα ανάλογα έχουν τροποποιημένη αλληλουχία ώστε να μη σχηματίζουν εξαμερή στο υποδόριο → ταχύτερη απορρόφηση → αιχμή που συμπίπτει με τη γευματική άνοδο της γλυκόζης. Η ανθρώπινη ινσουλίνη σχηματίζει εξαμερή → καθυστερημένη απορρόφηση, ένεση 30 min πριν από το γεύμα."
    ],
    "indications": [
      "Γευματικές (bolus) δόσεις σε ΣΔ τύπου 1 και σε εντατικοποίηση στον ΣΔ τύπου 2 (σχήμα B1: μία δόση πριν από το κύριο γεύμα, που προτιμάται).",
      "Διορθωτικές δόσεις. Αντλία συνεχούς υποδόριας έγχυσης (ανάλογα).",
      "Κύηση: ασφαλείς η lispro, η aspart, η FiAsp και η URLi."
    ],
    "contraindications": [
      "Υπογλυκαιμία.",
      "Νεφρική ανεπάρκεια: μείωση της δόσης κατά 25% σε eGFR 10–50 και κατά 50% σε eGFR < 10 (η ινσουλίνη απεκκρίνεται από τους νεφρούς).",
      "Διαβητική κετοξέωση με κάλιο < 3,3 mEq/L: καθυστέρηση της έναρξης ινσουλίνης μέχρι να διορθωθεί το κάλιο (η ινσουλίνη μεταφέρει K⁺ στα κύτταρα)."
    ],
    "adverse_effects": [
      "Υπογλυκαιμία, αύξηση βάρους (~4 kg), λιποδυστροφία στα σημεία ένεσης, υποκαλιαιμία (μετακίνηση K⁺ στα κύτταρα)."
    ],
    "pearls": [
      "Η δόση πριν από το γεύμα = ινσουλίνη για τους υδατάνθρακες του γεύματος + διόρθωση για την τρέχουσα γλυκόζη. Η καταμέτρηση υδατανθράκων αυξάνει την ακρίβεια.",
      "Η ταχεία ενδοφλέβια χορήγηση (bolus) δεν ενδείκνυται στην κετοξέωση: απότομη πτώση της ωσμωτικότητας.",
      "Σε όλους τους ασθενείς υπό ινσουλίνη (τύπου 1 και 2) προτιμώνται τα ανάλογα, για λιγότερες υπογλυκαιμίες. Σε όλους συνταγογραφείται γλυκαγόνη (η ρινική προτιμάται).",
      "Στην οξεία νόσο η ινσουλίνη δεν παραλείπεται ποτέ, ακόμη και με ναυτία ή εμέτους. Συνήθως χρειάζεται περισσότερη, όχι λιγότερη.",
      "Μετά τον τοκετό οι ανάγκες μειώνονται απότομα: άμεση μείωση της δόσης. Το ίδιο κατά τη μείωση των κορτικοειδών.",
      "Μετάβαση από ενδοφλέβια σε υποδόρια ινσουλίνη: η πρώτη υποδόρια ένεση γίνεται 15 min (ανάλογα) ή 30 min (διαλυτή) πριν από τη διακοπή της ενδοφλέβιας. Η βασική δίνεται 2 ώρες πριν."
    ],
    "abbreviations": "ΣυντομογραφίεςΣΔ τύπου 2: σακχαρώδης διαβήτης τύπου 2eGFR: estimated glomerular filtration rate = εκτιμώμενος ρυθμός σπειραματικής διήθησηςURLi: ultra-rapid lispro = υπερταχείας δράσης λισπρόFiAsp: fast-acting insulin aspart = ταχύτερης δράσης ασπαρτική ινσουλίνηΣΔ: σακχαρώδης διαβήτης",
