      "Ανάλογα μακράς δράσης: glargine (κατακρημνίζεται στο ουδέτερο pH του υποδορίου), detemir (σύνδεση με λευκωματίνη μέσω λιπαρού οξέος), degludec (σχηματισμός πολυεξαμερών) → σχεδόν σταθερή απελευθέρωση χωρίς αιχμή."
