    "brands_str": "",
    "content_parts": [
      "Διάγνωση",
      "Γλυκόζη νηστείας ≥ 126 mg/dl, ή γλυκόζη 2 ωρών στην καμπύλη με 75 g ≥ 200 mg/dl, ή τυχαία γλυκόζη ≥ 200 mg/dl με συμπτώματα, ή HbA1c ≥ 6,5% (προτυποποιημένη μέθοδος). Χωρίς συμπτώματα, επιβεβαίωση σε άλλη ημέρα. Προδιαβήτης: γλυκόζη νηστείας 100–125 mg/dl (διαταραγμένη γλυκόζη νηστείας) ή γλυκόζη 2 ωρών 140–199 mg/dl (διαταραγμένη ανοχή γλυκόζης). Περίπου 25% θα αναπτύξουν ΣΔ σε 3–5 χρόνια.",
      "Γλυκαιμικοί στόχοι",
      "Επιλογή φαρμάκου στον ΣΔ τύπου 2",
      "Με αθηροσκληρωτική καρδιαγγειακή νόσο, υψηλό κίνδυνο, καρδιακή ανεπάρκεια ή ΧΝΝ: αγωνιστής GLP-1 ή αναστολέας SGLT2 με αποδεδειγμένο όφελος, από την αρχή, με ή χωρίς μετφορμίνη και ανεξάρτητα από την HbA1c. Στην καρδιακή ανεπάρκεια και στη ΧΝΝ προτιμάται ο αναστολέας SGLT2. Χωρίς αυτά: αλλαγή τρόπου ζωής και μετφορμίνη. Η προσθήκη καθοδηγείται από την αποτελεσματικότητα στη γλυκόζη και στο βάρος. Πολύ υψηλή: τιρζεπατίδη, σεμαγλουτίδη, συνδυασμοί, ινσουλίνη. Υψηλή: λιραγλουτίδη, ντουλαγλουτίδη, μετφορμίνη, πιογλιταζόνη, σουλφονυλουρίες. Ενδιάμεση: αναστολείς DPP-4 και SGLT2. Έναρξη με 2 φάρμακα όταν η HbA1c είναι 1,5–2% πάνω από τον στόχο. Έναρξη με ινσουλίνη όταν υπάρχει καταβολισμός, HbA1c > 10% ή γλυκόζη ≥ 300 mg/dl. Έλεγχος HbA1c κάθε 3 μήνες. Αν δεν επιτευχθεί ο στόχος σε 2–3 μήνες, αλλαγή της θεραπείας.",
      "Ινσουλινοθεραπεία στον ΣΔ τύπου 2",
      "Α1: μετφορμίνη ± δισκία + αγωνιστής GLP-1 (προτιμάται) ή βασική ινσουλίνη. Α2: και τα δύο. B1 (προτιμάται): προσθήκη μίας γευματικής ινσουλίνης πριν από το κύριο γεύμα, με μείωση ή διακοπή των σουλφονυλουριών και των γλινιδών. B2: πλήρης εντατικοποίηση (σπάνια πλέον). B3: έτοιμα μείγματα. Σε όλα τα στάδια συνεχίζονται η μετφορμίνη, οι αναστολείς SGLT2 και οι αγωνιστές GLP-1, εφόσον λαμβάνονται.",
      "Ειδικές καταστάσεις",
      "ΣΔ τύπου 1: βασική ινσουλίνη μακράς δράσης + γευματικές δόσεις ταχείας ή υπερταχείας δράσης, ή αντλία. Τα μείγματα δεν έχουν θέση. LADA: βασική ινσουλίνη με αναστολέα DPP-4 ή αγωνιστή GLP-1, ± μετφορμίνη. MODY: το MODY2 (γλυκοκινάση) δεν χρειάζεται θεραπεία. Τα MODY3 και MODY4 απαντούν σε σουλφονυλουρίες. Το MODY5 θεραπεύεται με ινσουλίνη. Κύηση: ινσουλίνη (ανθρώπινη ή τα εγκεκριμένα ανάλογα). Η μετφορμίνη με σχετική ασφάλεια, συνήθως ανεπαρκής μόνη της. Έφηβοι με ΣΔ τύπου 2: μετφορμίνη αν HbA1c < 8,5% χωρίς συμπτώματα. Ινσουλίνη αν υπάρχει κέτωση ή κετοξέωση ή HbA1c > 8,5%. Δεν δίνονται σουλφονυλουρίες. Επώδυνη διαβητική νευροπάθεια: 1ο βήμα πρεγκαμπαλίνη ή ντουλοξετίνη, 2ο γκαμπαπεντίνη, 3ο συνδυασμός, 4ο οπιοειδή, τραμαδόλη, καψαϊκίνη.",
      "Επιστροφή στις κατηγορίες"
    ],
