    "pearls": [
      "Ιδιαιτερότητες: β-λακτάμες Στην ομάδα των β-λακταμικών αντιβιοτικών ανήκουν: Πενικιλλίνες Κεφαλοσπορίνες Κεφαμυκίνες Καρβαπενέμες Μονομπακτάμες Αναστολείς β-λακταμασών // Δεν είναι όλοι οι αναστολείς β-λακτάμες αλλά θα τους περιγράψουμε σε αυτήν την κατηγορία β-λακτάμες Μηχανισμός δράσης Αναστέλλουν τη σύνθεση του κυτταρικού τοιχώματος Συνδέονται με πενικιλλινοδεσμευτικές πρωτεΐνες →εμποδίζουν σχηματισμό συνδέσεων μεταξύ των αλύσων πεπτιδογλυκάνης. → Ενεργοποίηση βακτηριακών αυτολυσινών και θάνατος. Βακτηριοκτόνος δράση έναντι μικροοργανισμών σε φάση πολλαπλασιασμού Μηχανισμοί αντοχής Καταστροφή του μορίου από ένζυμα (β-λακταμάσες) Μεταλλάξεις και μείωση της συγγένειας των πενικιλλινοδεσμευτικών πρωτεϊνών για τις β-λακτάμες Μείωση της συγκέντρωσης στις θέσεις όπου ασκούν τη δράση τους (π.χ. πορίνες, αντλίες εκροής) β-λακτάμες Φαρμακοκινητική Συχνά μέτρια απορρόφηση από το γαστρεντερικό – αρκετά μόρια διαθέσιμα μόνο ενδοφλέβια. Συχνά βραχείς t1/2(<1-2h). Χορήγηση πολλές φορές στη διάρκεια της ημέρας (εξαίρεση κεφτριαξόνη και ερταπενέμη) Απέκκριση κατά κανόνα από τους νεφρούς –απαιτείται προσαρμογή της δόσης Κατανομή σε πλάσμα και διάμεσο χώρο, ενώ υπολείπεται η συγκέντρωση ενδοκυττάρια Ιστική κατανομή σε ικανοποιητικά επίπεδα με εξαίρεση προστάτη, οφθαλμό και ΕΝΥ Σημαντική σύνδεση με πρωτεΐνες στο πλάσμα β-λακτάμες Φαρμακοδυναμική Χρονοεξαρτώμενη βακτηριοκτόνος δράση Περιορισμένο ή απών μετααντιβιοτικό φαινόμενο (αναστολή της βακτηριακής αυξητικής φάσης επί συγκέντρωσης μικρότερης της MIC) Η διάρκεια κατά την οποία επιτυγχάνονται συγκεντρώσεις μεγαλύτερες από την MIC απαραίτητη για βακτηριοκτόνο δράση ποικίλλει ανάλογα με τη βαρύτητα και την εστία της λοίμωξης 40% για λοιμώξεις ΩΡΛ ή αναπνευστικού 100% και επίπεδα 4-8x MIC για μηνιγγίτιδα, ενδοκαρδίτιδα, ανοσοκατεσταλμένους ασθενείς *Ο βραχύς t1/2 σε συνδυασμό με τα προαναφερθέντα καθιστούν αναγκαίες πολλαπλές χορηγήσεις/ημέρα. β-λακτάμες Ανεπιθύμητες ενέργειες Αντιδράσεις υπερευαισθησίας δυνητικά θανατηφόρες (κνίδωση, εξάνθημα, καταπληξία, αγγειοοίδημα) Τοξικότητα σπάνια και ποικίλη ανάλογα με το μόριο Σπασμοί, συγχυτικό- διεγερτική κατάσταση Αιμολυτική αναιμία, ουδετεροπενία, θρομβοπενία Διαταραχή πηκτικού μηχανισμού (πενικιλλίνη G σε υψηλές δόσεις, τικαρκιλλίνη) Ηπατίτιδα Οξεία διάμεση νεφρίτιδα Υψηλό φορτίο νατρίου (πενικιλλίνη)-επιβάρυνση σε νεφρική και καρδιακή ανεπάρκεια Διάρροια – λοίμωξη από C. difficile Εξάνθημα μετά χορήγηση αμοξυκιλλίνης σε περίπτωση EBV λοίμωξης Φυσικές πενικιλλίνες: Πενικιλλίνη G (IV) και Πενικιλλίνη V (PO) Στενό φάσμα δράσης: β-αιμολυτικοί στρεπτόκοκκοι πνευμονιόκοκκος ευαίσθητος στην πενικιλλίνη ορισμένα αναερόβια π.χ.. πεπτοστρεπτόκοκκοι, ακτινομύκητες) Treponema pallidum Pasteurella multocida Στερούνται δραστικότητας έναντι σταφυλόκοκκων* και gram αρνητικών μικροβίων(εξαίρεση η P. multocida) Θεραπεία εκλογής για σύφιλη και φαρυγγίτιδα από S. pyogenes Πρόληψη για υποτροπιάζον ερυσίπελας, υποτροπές οξέος ρευματικού πυρετού, πνευμονιοκοκκικής λοίμωξης μετά σπληνεκτομή Η βενζαθινική πενικιλλίνη G(IM) έχει μακρά δράση και επιτυγχάνει θεραπευτικά επίπεδα για 14-21 ημέρες."
    ],
    "abbreviations": "Συντομογραφίες EBV : Epstein-Barr Virus = ιός Epstein-Barr IM : ενδομυϊκή χορήγηση (intramuscular) IV : ενδοφλέβια χορήγηση (intravenous) MIC : Minimum Inhibitory Concentration = ελάχιστη ανασταλτική συγκέντρωση PO : από του στόματος χορήγηση (per os) ΕΝΥ : Εγκεφαλονωτιαίο Υγρό ΣΜΝ : Σεξουαλικώς Μεταδιδόμενα Νοσήματα ΩΡΛ : Ωτορινολαρυγγολογικό / Ωτορινολαρυγγολογία",
