      "Κεφοταξίμη / Κεφτριαξόνη: S. pneumoniae, N. meningitidis, N. gonorrhoeae, Εντεροβακτηριακά.",
      "Κεφταζιδίμη: Ειδική δραστικότητα έναντι Pseudomonas aeruginosa (μειωμένη δράση σε Gram+).",
      "(Όχι δράση σε Λιστέρια, Εντερόκοκκο, MRSA, αναερόβια)."
