    "indications": [
      "Νευρικό (ΚΝΣ): Βακτηριακή Μηνιγγίτιδα (Κεφτριαξόνη/Κεφοταξίμη IV + Βανκομυκίνη) — Άμεση χορήγηση Κεφτριαξόνης IV στον κρίσιμο ασθενή με υποψία μηνιγγίτιδας.",
      "Πεπτικό: Αυτόματη Βακτηριακή Περιτονίτιδα (ΑΒΠ) σε κιρρωτικούς (Κεφοταξίμη/Κεφτριαξόνη - θεραπεία εκλογής), Σαλμονέλλωση / Σιγκέλλωση.",
      "Αναπνευστικό: Σοβαρή Πνευμονία κοινότητας, Νοσοκομειακή πνευμονία (Κεφταζιδίμη για P. aeruginosa).",
      "Ουροποιητικό: Οξεία Πυελονεφρίτιδα, Επιπλεγμένες ουρολοιμώξεις.",
      "Γεννητικό / ΣΜΝ: Γονόρροια (N. gonorrhoeae - Κεφτριαξόνη IM εφάπαξ), Χημειοπροφύλαξη μηνιγγιτιδόκοκκου (250mg IM σε εγκύους).",
      "Μυοσκελετικό: Σηπτική αρθρίτιδα / Οστεομυελίτιδα από Gram(-).",
      "Τα κοινά χαρακτηριστικά των β-λακταμών υπάρχουν στην ενότητα Φυσικές Πενικιλλίνες .",
      "Συντομογραφίες AmpC : β-λακταμάση τύπου AmpC IM : ενδομυϊκή χορήγηση (intramuscular) IV : ενδοφλέβια χορήγηση (intravenous) MRSA : Methicillin-Resistant Staphylococcus aureus = S. aureus ανθεκτικός στη μεθικιλλίνη MSSA : Methicillin-Susceptible Staphylococcus aureus = S. aureus ευαίσθητος στη μεθικιλλίνη PO : από του στόματος χορήγηση (per os) ΑΒΠ : Αυτόματη Βακτηριακή Περιτονίτιδα ΕΝΥ : Εγκεφαλονωτιαίο Υγρό ΚΝΣ : Κεντρικό Νευρικό Σύστημα ΣΜΝ : Σεξουαλικώς Μεταδιδόμενα Νοσήματα ΩΡΛ : Ωτορινολαρυγγολογικό / Ωτορινολαρυγγολογία",
      "Επιστροφή στις κατηγορίες"
    ],
    "pearls": [
      "Ιδιαιτερότητες: Κεφαλοσπορίνες 3ης γενιάς• (κεφιξίμη(PO), κεφντιτορένη(PO), κεφοταξίμη(IV), κεφτριαξόνη(IV), κεφταζιδίμη(IV) Φάσμα Ευρύτερη Gram(-) κάλυψη (συμπεριλαμβάνει εντεροβακτηριακά), ενώ διατηρούν σε γενικές γραμμές την δραστικότητά τους έναντι στρεπτόκοκκων και MSSA. Εξαίρεση η κεφταζιδίμη Οι από του στόματος χορηγούμενες έχουν μικρότερη βιοδιαθεσιμότητα από της κεφαλοσπορίνες 1ης γενιάς Χορηγούνται σε μη σοβαρές λοιμώξεις ΩΡΛ, κατώτερου αναπνευστικού ή ως συνέχιση ενδοφλέβιας θεραπείας π.χ. για λοιμώξεις ουροποιητικού Οι ενδοφλέβια χορηγούμενες χαρακτηρίζονται από καλή ιστική κατανομή (και στο ΕΝΥ και ιδιαίτερα επί φλεγμονής) Χρησιμοποιούνται στη θεραπεία της μηνιγγίτιδας, και σε σοβαρές λοιμώξεις κατώτερου αναπνευστικού, βακτηριαιμία, επιπλεγμένες λοιμώξεις ουροποιητικού, ενδοκοιλιακές, δέρματος και μαλακών μορίων Απουσία δραστικότητας έναντι λιστέριας, εντερόκοκκων, MRSA, ενδοκυττάριων βακτηρίων, Κεφαλοσπορίνες 3ης γενιάς Κεφοταξίμη/κεφτριαξόνη Αν και η δραστικότητα έναντι των σταφυλόκοκκων υπολείπεται των 1ης γενιάς, εξαιρετική δραστικότητα έναντι πνευμονιόκοκκου, μηνιγγιτιδόκοκκου και γονόκοκκου. Πολύ καλή δραστικότητα έναντι πολλών εντεροβακτηριακών και H. influenzae β-λακταμάση(+). Ωστόσο κίνδυνος αποτυχίας σε βακτήρια που φέρουν χρωμοσωμικές AmpC β-λακταμάσες Κεφταζιδίμη Η μοναδική κεφαλοσπορίνη 3ης γενιάς με ιδιαίτερη δραστικότητα έναντι της P. aeruginosa. Αντίθετα, δεν έχει καλή δραστικότητα έναντι Gram(+) -> Κατάλληλη ως αιτιολογική θεραπεία έναντι P. Aeruginosa"
    ],
    "abbreviations": "Συντομογραφίες AmpC : β-λακταμάση τύπου AmpC IM : ενδομυϊκή χορήγηση (intramuscular) IV : ενδοφλέβια χορήγηση (intravenous) MRSA : Methicillin-Resistant Staphylococcus aureus = S. aureus ανθεκτικός στη μεθικιλλίνη MSSA : Methicillin-Susceptible Staphylococcus aureus = S. aureus ευαίσθητος στη μεθικιλλίνη PO : από του στόματος χορήγηση (per os) ΑΒΠ : Αυτόματη Βακτηριακή Περιτονίτιδα ΕΝΥ : Εγκεφαλονωτιαίο Υγρό ΚΝΣ : Κεντρικό Νευρικό Σύστημα ΣΜΝ : Σεξουαλικώς Μεταδιδόμενα Νοσήματα ΩΡΛ : Ωτορινολαρυγγολογικό / Ωτορινολαρυγγολογία",
    "type": "substance"
