    "pearls": [
      "Ιδιαιτερότητες: Καρβαπενέμες (ερταπενέμη, ιμιπενέμη/σιλαστατίνη, μεροπενέμη) Φάσμα Έχουν το ευρύτερο φάσμα έναντι Gram(-) Δραστικές έναντι MSSA, στρεπτόκοκκων, και πλην ερταπενέμης P. aeruginosa και Acinetobacter Επίσης, δραστικές έναντι εντεροβακτηριακών που παράγουν AmpC β-λακταμάσες και ESBL. Δραστικές έναντι αναερόβιων Μέτρια δραστικότητα έναντι εντερόκοκκων (πλην ερταπενέμης) Στην κλινική πράξη χρησιμοποιούνται για νοσοκομειακές λοιμώξεις, λοιμώξεις από ESBL βακτήρια, ενδοκοιλιακές λοιμώξεις, μεικτές λοιμώξεις από αερόβια/αναερόβια, μηνιγγίτιδα (μεροπενέμη) Η ερταπενέμη δεν είναι κατάλληλη ως εμπειρική θεραπεία για νοσοκομειακές λοιμώξεις, ενώ μπορεί να χρησιμοποιηθεί έναντι ESBL λοιμώξεων. Το φαρμακοκινητικό της προφίλ επιτρέπει χορήγηση μια φορά την ημέρα. Η σιλαστατίνη συγχορηγείται με την ιμιπενέμη για να παρεμποδίσει το μεταβολισμό της σε τοξικό παράγωγο στους νεφρούς. Μείωση επιληπτογόνου ουδού. Αλληλεπίδραση με το βαλπροϊκό οξύ έχει ως αποτέλεσμα τη μείωση των επιπέδων του. Αναγκαία η περιφρούρηση της χρήσης τους για αποφυγή διάδοσης αντοχής."
    ],
    "abbreviations": "Συντομογραφίες AmpC : β-λακταμάση τύπου AmpC ESBL : Extended-Spectrum β-Lactamases = β-λακταμάσες εκτεταμένου φάσματος IV : ενδοφλέβια χορήγηση (intravenous) MSSA : Methicillin-Susceptible Staphylococcus aureus = S. aureus ευαίσθητος στη μεθικιλλίνη spp. : species = διάφορα είδη του ίδιου γένους ΑΒΠ : Αυτόματη Βακτηριακή Περιτονίτιδα ΚΝΣ : Κεντρικό Νευρικό Σύστημα",
