    "pearls": [
      "Ιδιαιτερότητες: Πολυμυξίνες (κολιστίνη και πολυμυξίνη Β) Μηχανισμός δράσης Λειτουργούν ως «απορρυπαντικά» συνδεόμενες με φωσφολιπίδια της κυτταρικής μεμβράνης Gram(-) και προκαλούν διαρροή περιεχομένων του κυττάρου και κυτταρικό θάνατο. Είναι βακτηριοκτόνες. Φάσμα Εντεροβακτηριακά, P. aeruginosa, Acinetobacter spp Δεν περιλαμβάνονται Gram(+), αναερόβια, Serratia spp, Proteus spp, Providencia spp, Morganella spp, Burkholderia spp και Gram(-) κόκκοι όπως π.χ Neisseria spp Στην κλινική πράξη είναι αντιβιοτικά τελευταίας γραμμής έναντι πολυανθεκτικών Gram(-) Συγκριτικές μελέτες με νεότερους συνδυασμούς β-λακταμικών αντιβιοτικών με αναστολείς λακταμάσης υποδεικνύουν ότι ακόμη και σε βελτιστοποιημένα δοσολογικά σχήματα η αποτελεσματικότητα της κολιστίνης υπολείπεται. Φαρμακοκινητική/Φαρμακοδυναμική Δεν απορροφώνται από το γαστρεντερικό Η κολιστίνη έχει πολύπλοκη φαρμακοκινητική και επιτυγχάνει θεραπευτικά επίπεδα στα ούρα, ενώ η πολυμυξίνη Β επαναρροφάται σχεδόν πλήρως στα νεφρικά σωληνάρια AUC/MIC ο φαρμακοδυναμικός δείκτης που συνδέεται με επιτυχή έκβαση Ανεπιθύμητες ενέργειες Νεφροτοξικότητα Νευροτοξικότητα"
    ],
