      "Ιδιαιτερότητες: Αμινογλυκοσίδες (αμικασίνη, τομπραμυκίνη, γενταμικίνη, στρεπτομυκίνη, πλαζομικίνη) Μηχανισμός δράσης Παρεμποδίζουν την πρωτεϊνοσύνθεση συνδεόμενες με την ριβοσωμική υπομονάδα 30S. Βακτηριοκτόνος δράση. Φάσμα Δραστικές έναντι των περισσότερων Gram(-) συμπεριλαμβανομένων εντεροβακτηριακών, ψευδομονάδας, Αcinetobacter spp Δεν είναι δραστικές έναντι αναερόβιων, άτυπων παθογόνων αναπνευστικού Συνεργική δράση έναντι Gram(+) (σταφυλόκοκκοι, στρεπτόκοκκοι, εντερόκοκκοι) σε συνδυασμό με β-λακτάμες ή γλυκοπεπτίδια, ενώ δεν έχουν επαρκή δραστικότητα ως μονοθεραπεία Η πλαζομικίνη συνήθως διατηρεί την δραστικότητά της ακόμη και έναντι πολυανθεκτικών Gram(-) εντεροβακτηριακών Αμικασίνη και στρεπτομυκίνη χρησιμοποιούνται και ως αντιμυκοβακτηριδιακά. Στην κλινική πράξη χρησιμοποιούνται σε συνδυασμό με β-λακτάμες για σοβαρές λοιμώξεις από Gram(-) και σε συνεργικούς συνδυασμούς για θεραπεία λοιμώξεων από Gram(+) όπως η λοιμώδης ενδοκαρδίτιδα Ως μονοθεραπεία μπορούν να χρησιμοποιηθούν για ουρολοίμωξη, τουλαραιμία, πανώλη Αμινογλυκοσίδες (αμικασίνη, τομπραμυκίνη, γενταμικίνη, στρεπτομυκίνη, πλαζομικίνη) Φαρμακοκινητική/Φαρμακοδυναμική Χορήγηση IV ή ενδομυικά(για αμικασίνη, τομπραμυκίνη, γενταμυκίνη) Μετα-αντιβιοτικό φαινόμενο Συγκέντρωση-εξαρτώμενη δράση Στα ούρα επιτυγχάνουν συγκεντρώσεις 25-100x του πλάσματος Κακή διείσδυση σε ΕΝΥ, βρογχικές εκκρίσεις και χοληφόρο δένδρο Η χορήγηση 1x/d μειώνει τον κίνδυνο νεφροτοξικότητας Ανεπιθύμητες ενέργειες Νεφροτοξικότητα Ωτοτοξικότητα Νευρομυικός αποκλεισμός-μυασθενική κρίση"
