      "Ιδιαιτερότητες: Λινκοσαμίδες Στην κατηγορία αυτή ανήκει η κλινδαμυκίνη Μηχανισμός δράσης Παρεμποδίζει την πρωτεϊνοσύνθεση συνδεόμενη με την ριβοσωμική υπομονάδα 50S.Βακτηριοστατική. (Βακτηριοκτόνος για συγκεκριμένα παθογόνα σε υψηλότερες δόσεις) Φάσμα Δραστικότητα έναντι Gram(+) αναερόβιων (με εξαίρεση C.difficile), S. pyogenes, S. aureus (σε κάποιες περιπτώσεις και MRSA. Λιγότερο ενεργή έναντι Gram(-) αναερόβιων . Επίσης ενεργή έναντι C. trachomatis, Pneumocystis spp, Actinomyces spp, Toxplasma spp Κακή δραστικότητα έναντι εντερόκοκκων και Gram(-) αεροβίων Στην κλινική πράξη χρησιμοποιείται σε λοιμώξεις στοματικές, ως χημειοπροφύλαξη για οδοντιατρικές επεμβάσεις, σε λοιμώξεις δέρματος/μαλακών μορίων και σε ενδοκοιλιακές λοιμώξεις Χρησιμοποιείται ως ενισχυτική αγωγή με σκοπό να μειώσει την παραγωγή τοξινών σε αντίστοιχες λοιμώξεις Εξαιρετική PO βιοδιαθεσιμότητα Πιθανή διασταυρούμενη αντοχή σε περίπτωση αντοχής στην ερυθρομυκίνη. Ανεπιθύμητες ενέργειες διάρροια, ναυτία, έμετος"
