    "brands_str": "XARELTO, ODELO, RIVAROLTO, RUNAPLAX, XAREBEN, XAVERTIA, ROXEGO, RIXAVEN, ENKIA, BLOMENSY, όλα τα σκευάσματα στον Γαληνό",
    "mechanism": [
      "Άμεση, εκλεκτική και αναστρέψιμη αναστολή ενός παράγοντα: της θρομβίνης (IIa, δαβιγατράνη, σε ελεύθερη και δεσμευμένη μορφή) ή του Xa (-ξαμπάνες). Ο Xa είναι το σημείο σύνδεσης ενδογενούς και εξωγενούς οδού και, με τον Va, ενεργοποιεί την προθρομβίνη.",
      "Μέγιστη δράση σε 1,5–4 h → η ριβαροξαμπάνη και η απιξαμπάνη δεν χρειάζονται αρχική επικάλυψη με ηπαρίνη.",
      "Αλληλεπιδράσεις μέσω P-gp (όλα) και CYP3A4 (ριβαροξαμπάνη, απιξαμπάνη, εδοξαμπάνη)."
    ],
    "indications": [
      "Πρόληψη ΑΕΕ και συστηματικής εμβολής σε μη βαλβιδική κολπική μαρμαρυγή: προτιμώνται της βαρφαρίνης.",
      "Θεραπεία και δευτερογενής πρόληψη της φλεβικής θρομβοεμβολής: προτιμώνται στους περισσότερους ασθενείς χωρίς ενεργό καρκίνο.",
      "Παιδιά: θεραπεία της φλεβικής θρομβοεμβολής (δαβιγατράνη, ριβαροξαμπάνη, απιξαμπάνη). Ριβαροξαμπάνη σε χαμηλή δόση με ασπιρίνη: στεφανιαία νόσο ή συμπτωματική περιφερική αρτηριακή νόσο, και μετά από οξύ στεφανιαίο σύνδρομο.",
      "Πρόληψη φλεβικής θρομβοεμβολής μετά από αρθροπλαστική ισχίου ή γόνατος."
    ],
    "contraindications": [
      "Ενεργός κλινικά σημαντική αιμορραγία.",
      "Βλάβη ή κατάσταση με σημαντικό κίνδυνο μείζονος αιμορραγίας (π.χ. πρόσφατο γαστρεντερικό έλκος, κακοήθεια με υψηλό κίνδυνο αιμορραγίας).",
      "Ηπατική νόσος με διαταραχή της πήξης και κίνδυνο αιμορραγίας (ριβαροξαμπάνη: και κίρρωση Child-Pugh B και C).",
      "Ταυτόχρονη θεραπεία με άλλο αντιπηκτικό (εκτός από τη μετάβαση από ένα αντιπηκτικό σε άλλο).",
      "Δαβιγατράνη: κάθαρση κρεατινίνης < 30 ml/min. Ισχυροί αναστολείς P-gp (κετοκοναζόλη, κυκλοσπορίνη, ιτρακοναζόλη, δρονεδαρόνη).",
      "Προσθετικές (μηχανικές) καρδιακές βαλβίδες. Μέτρια ή σοβαρή στένωση μιτροειδούς. Αντιφωσφολιπιδικό σύνδρομο με αρτηριακή θρόμβωση.",
      "Κύηση και γαλουχία (ριβαροξαμπάνη, απιξαμπάνη).",
      "Ριβαροξαμπάνη με αντιαιμοπεταλιακά: όχι σε ιστορικό ΑΕΕ ή παροδικού ισχαιμικού επεισοδίου."
    ],
    "adverse_effects": [
      "Αιμορραγία."
    ],
    "pearls": [
      "Πλεονεκτήματα: ταχεία έναρξη, σταθερή δόση, χωρίς παρακολούθηση INR, λιγότερες αλληλεπιδράσεις.",
      "Διακοπή 1–2 ημέρες πριν από προγραμματισμένο χειρουργείο, όταν η νεφρική λειτουργία είναι φυσιολογική.",
      "Αλλαγή αγωγής: από ΗΧΜΒ σε απιξαμπάνη, όταν θα έπρεπε να γίνει η επόμενη δόση ΗΧΜΒ. Από βαρφαρίνη σε απιξαμπάνη, όταν το INR πέσει κάτω από 2,0.",
      "Απιξαμπάνη: διακοπή τουλάχιστον 48 ώρες πριν από επέμβαση μέτριου ή υψηλού αιμορραγικού κινδύνου. Προσοχή σε ραχιαία ή επισκληρίδιο αναισθησία ή παρακέντηση (κίνδυνος επισκληρίδιου αιματώματος)."
    ],
