      "Κύηση και γαλουχία (ριβαροξαμπάνη, απιξαμπάνη).",
      "Ριβαροξαμπάνη με αντιαιμοπεταλιακά: όχι σε ιστορικό ΑΕΕ ή παροδικού ισχαιμικού επεισοδίου."
