    "brands_str": "KONAKION, KONAKION MM, VITALIPID (συνδυασμός), Κυκλοφορούν μόνο 3 σκευάσματα, όλα τα σκευάσματα στον Γαληνό",
    "mechanism": [
      "Πρωταμίνη: πολυκατιονικό μόριο που δεσμεύει την ανιοντική ηπαρίνη. Βιταμίνη Κ₁: αποκαθιστά την καρβοξυλίωση των παραγόντων. Ιδαρουσιζουμάμπη: μονοκλωνικό τμήμα αντισώματος που δεσμεύει τη δαβιγατράνη. Andexanet: τροποποιημένος Xa που «παγιδεύει» τους αναστολείς. Τρανεξαμικό οξύ: αναστολή της σύνδεσης του πλασμινογόνου με την ινική."
    ],
    "indications": [
      "Αναστροφή της αντιπηκτικής δράσης σε αιμορραγία ή επείγουσα επέμβαση.",
      "Συμπύκνωμα προθρομβίνης: και η συγγενής ανεπάρκεια παραγόντων εξαρτώμενων από τη βιταμίνη Κ, όταν δεν υπάρχει ειδικό σκεύασμα του παράγοντα.",
      "Ιδαρουσιζουμάμπη: ασθενείς υπό δαβιγατράνη που χρειάζονται ταχεία αναστροφή για επείγον χειρουργείο ή επεμβατική πράξη, ή σε απειλητική για τη ζωή ή ανεξέλεγκτη αιμορραγία. Δεσμεύει τη δαβιγατράνη με συγγένεια ~300 φορές μεγαλύτερη από τη συγγένεια της δαβιγατράνης για τη θρομβίνη.",
      "Τρανεξαμικό οξύ: αιμορραγίες από γενικευμένη ή τοπική ινωδόλυση, αιμορραγία από ινωδολυτικό, επεμβάσεις ΩΡΛ (αμυγδαλεκτομή, εξαγωγές δοντιών, και σε αιμοφιλικούς), μείζονες επεμβάσεις θώρακα, κοιλίας και καρδιάς, μηνορραγία, επίσταξη, τραυματικό ύφαιμα, κληρονομικό αγγειοοίδημα."
    ],
    "contraindications": [
      "Συμπύκνωμα προθρομβίνης (ΠΧΠ Prothromplex): γνωστή αλλεργία στην ηπαρίνη ή ιστορικό θρομβοπενίας από ηπαρίνη, επειδή το σκεύασμα περιέχει ηπαρίνη. Υπερευαισθησία.",
      "Τρανεξαμικό οξύ: σοβαρή νεφρική ανεπάρκεια (συσσώρευση), υπαραχνοειδής αιμορραγία, ενεργός θρομβοεμβολική νόσος, ιστορικό φλεβικής ή αρτηριακής θρόμβωσης, ιστορικό σπασμών, ινωδολυτικές καταστάσεις μετά από καταναλωτική διαταραχή πήξης (εκτός αν επικρατεί η ενεργοποίηση της ινωδόλυσης με σοβαρή οξεία αιμορραγία)."
    ],
    "adverse_effects": [],
    "pearls": [
      "Συμπύκνωμα προθρομβίνης: μόνο όταν χρειάζεται ταχεία διόρθωση (μείζων αιμορραγία, επείγον χειρουργείο). Σε κάθε άλλη περίπτωση αρκεί η μείωση της δόσης του κουμαρινικού ή/και η βιταμίνη Κ. Ο ασθενής υπό κουμαρινικό έχει συχνά υποκείμενη υπερπηκτικότητα, που το σκεύασμα μπορεί να επιδεινώσει."
    ],
